Examples Example 1: Expanding Scrolling Text in Place A large block of text is scrolled through a small marquee area of the page. A button lets the user stop the scrolling and display the entire block of text. Note This code example requires that both CSS and JavaScript be turned on and available. The CSS component #scrollContainer { background-color : darkblue; left : 10px ; overflow : hidden; top : 50px ; visibility : visible;
} .scrolling { height : 50px ; position : absolute; width : 200px ;
} .notscrolling { margin : 10px ; width : 500px ;
} #scrollingText { color : white; top : 0px ;
} .scrolling #scrollingText { position : absolute;
} The script and HTML content: < script > var tid; function init ( ) { var st = document . getElementById ( 'scrollingText' );
  st. style . top = '0px' ; initScrolling ();
} function initScrolling ( ) {
  tid = setInterval ( 'scrollText()' , 300 );
} function scrollText ( ) { var st = document . getElementById ( 'scrollingText' ); if ( parseInt (st. style . top ) > (st. offsetHeight *(- 1 ) + 8 )) {
    st. style . top = ( parseInt (st. style . top ) - 5 ) + 'px' ;
  } else { var sc = document . getElementById ( 'scrollContainer' );
    st. style . top = parseInt (sc. offsetHeight ) + 8 + 'px' ;
  }
} function toggle ( ) { var scr = document . getElementById ( 'scrollContainer' ); if (scr. className == 'scrolling' ) {
    scr. className = 'notscrolling' ; clearInterval (tid); document . getElementById ( 'scrollButton' ). value = "Shrink" ;
  } else {
    scr. className = 'scrolling' ; initScrolling (); document . getElementById ( 'scrollButton' ). value = "Expand" ;
  }
}

