Examples Example 1: Updating screen reader settings for stock price update alerts The script below will update a stock value in an aria-live component every 10 seconds. If the user presses the "Turn Announcements Off" button, their screen reader will stop making announcements when the stock value changes; if they press the "Turn Announcements On" button, the announcements will start again. The JavaScript < script > document . addEventListener ( "DOMContentLoaded" , function ( e ) { const stockBox = document . querySelector ( "#stock-box" ); const stockMovement = document . querySelector ( "#stock-movement" ); const onBtn = document . querySelector ( "#live-on" ); const offBtn = document . querySelector ( "#live-off" ); const stocks = new Array ( "stock went down" , "stock stayed the same" , "stock went up" ); let loopCount = 0 ;	

  onBtn. addEventListener ( "click" , modifyLive, false );
  offBtn. addEventListener ( "click" , modifyLive, false ); function modifyLive ( e ){ let elm = e. currentTarget ; let liveState = elm. getAttribute ( "id" ); if (liveState === "live-off" ){
      stockBox. setAttribute ( "aria-live" , "off" );
      onBtn. setAttribute ( "aria-pressed" , "false" );
      offBtn. setAttribute ( "aria-pressed" , "true" );
    } else {
      stockBox. setAttribute ( "aria-live" , "assertive" );
      onBtn. setAttribute ( "aria-pressed" , "true" );
      offBtn. setAttribute ( "aria-pressed" , "false" );      
    }
  } setInterval ( () => { if (loopCount > 2 ){
      loopCount = 0 ;
    }
    stockMovement. innerHTML = stocks[loopCount];
      loopCount++;
    }, 10000 )
  }); </ script > The HTML < body > < h1 > Turbo Encabulator Stock Information </ h1 > < div id = "stock-box" aria-atomic = "true" aria-live = "assertive" > < span > Turbo Encabulator Stock Price: </ span > < span id = "stock-movement" > stock went up </ span > </ div > < p > Use the buttons to toggle screen reader announcements of stock changes: </ p > < div > < button aria-pressed = "true" id = "live-on" type = "button" > Turn Announcements On </ button > < button aria-pressed = "false" id = "live-off" type = "button" > Turn Announcements Off </ button > </ div > </ body > Working example of this code: Demonstration of toggling ARIA alerts .

